create table if not exists public.ce_billing_subscriptions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,plan text not null check(plan in('FREE','PRO','BUSINESS','ENTERPRISE')),status text not null check(status in('TRIALING','ACTIVE','PAST_DUE','CANCELED')),period_start timestamptz not null,period_end timestamptz not null,external_subscription_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id));create table if not exists public.ce_billing_usage(tenant_id uuid not null,period_start timestamptz not null,entitlement_key text not null,used_count bigint not null default 0 check(used_count>=0),updated_at timestamptz not null default now(),primary key(tenant_id,period_start,entitlement_key));alter table public.ce_billing_subscriptions enable row level security;alter table public.ce_billing_usage enable row level security;revoke all on public.ce_billing_subscriptions,public.ce_billing_usage from public,anon,authenticated;grant select,insert,update,delete on public.ce_billing_subscriptions,public.ce_billing_usage to service_role;